import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import {
  ArrowLeft, ArrowRight, Check, ChevronDown, ChevronRight, Heart, Info, Menu,
  Minus, Plus, Search, ShoppingBag, UserRound, X
} from 'lucide-react';
import './styles.css';

const photos = [
  'https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=1400&q=85',
  'https://images.unsplash.com/photo-1551107696-a4b0c5a0d9a2?auto=format&fit=crop&w=1400&q=85',
  'https://images.unsplash.com/photo-1600185365483-26d7a4cc7519?auto=format&fit=crop&w=1400&q=85'
];
const colors = [
  { name: 'Sky blue', value: '#607b91' },
  { name: 'Onyx black', value: '#202326' },
  { name: 'Stone grey', value: '#a8a6a0' }
];
const sizes = ['7', '7.5', '8', '8.5', '9', '9.5', '10', '10.5', '11', '11.5', '12', '13'];
const soldOut = ['7.5', '10.5'];

function App() {
  const [photo, setPhoto] = useState(0);
  const [color, setColor] = useState(colors[0]);
  const [size, setSize] = useState('');
  const [sizeOpen, setSizeOpen] = useState(false);
  const [quantity, setQuantity] = useState(1);
  const [wishlist, setWishlist] = useState(false);
  const [cartCount, setCartCount] = useState(0);
  const [notice, setNotice] = useState('');
  const [guideOpen, setGuideOpen] = useState(false);
  const [tab, setTab] = useState('Details');
  const [openFaq, setOpenFaq] = useState(null);
  const sizeMenuRef = useRef(null);
  const guideRef = useRef(null);

  useEffect(() => {
    if (!guideOpen) return;
    guideRef.current?.focus();
    const onKey = (e) => e.key === 'Escape' && setGuideOpen(false);
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [guideOpen]);

  const addToCart = () => {
    if (!size) {
      setNotice('Please choose a size before adding this item to your bag.');
      setSizeOpen(true);
      sizeMenuRef.current?.focus();
      return;
    }
    setCartCount((count) => count + quantity);
    setNotice(`${quantity} ${quantity === 1 ? 'pair' : 'pairs'} of Trail Runner 2 added to your bag.`);
  };
  const changePhoto = (direction) => setPhoto((current) => (current + direction + photos.length) % photos.length);

  return (
    <div className="app">
      <div className="announcement">Free shipping on orders over $75 <span aria-hidden="true">•</span> Easy returns</div>
      <header className="header">
        <a className="logo" href="/" aria-label="Stride home"><span>STRIDE</span><small>GO FURTHER</small></a>
        <nav className="main-nav" aria-label="Main navigation">
          {['Men', 'Women', 'Kids', 'Trail', 'New arrivals'].map((item) => <a href={`#${item.toLowerCase().replace(' ', '-')}`} key={item}>{item}</a>)}
        </nav>
        <div className="header-actions">
          <button className="icon-button" aria-label="Search"><Search size={19} /></button>
          <button className="icon-button" aria-label="Your account"><UserRound size={19} /></button>
          <button className="bag-button" aria-label={`Shopping bag, ${cartCount} items`}><ShoppingBag size={19} /><span>{cartCount}</span></button>
        </div>
        <button className="mobile-menu icon-button" aria-label="Open menu"><Menu size={22} /></button>
      </header>

      <main>
        <div className="breadcrumbs" aria-label="Breadcrumb">
          <a href="#shop">Shop</a><ChevronRight size={14} aria-hidden="true" /><a href="#trail">Trail</a><ChevronRight size={14} aria-hidden="true" /><span aria-current="page">Trail Runner 2</span>
        </div>
        <section className="product-layout" aria-labelledby="product-title">
          <div className="gallery">
            <div className="photo-frame">
              <img src={photos[photo]} alt={`Trail Runner 2 trail shoe, view ${photo + 1} of ${photos.length}`} />
              <button className="gallery-arrow prev" onClick={() => changePhoto(-1)} aria-label="Previous product photo"><ArrowLeft size={18} /></button>
              <button className="gallery-arrow next" onClick={() => changePhoto(1)} aria-label="Next product photo"><ArrowRight size={18} /></button>
              <div className="photo-count" aria-live="polite">{String(photo + 1).padStart(2, '0')} / {String(photos.length).padStart(2, '0')}</div>
            </div>
            <div className="thumbnail-list" aria-label="Product photos">
              {photos.map((src, index) => <button className={index === photo ? 'thumbnail active' : 'thumbnail'} key={src} onClick={() => setPhoto(index)} aria-label={`View product photo ${index + 1}`} aria-pressed={index === photo}><img src={src} alt="" /></button>)}
            </div>
          </div>

          <div className="product-info">
            <p className="eyebrow">TRAIL COLLECTION <span>•</span> NEW</p>
            <div className="title-row">
              <h1 id="product-title">Trail Runner 2</h1>
              <button className={wishlist ? 'heart active' : 'heart'} onClick={() => setWishlist(!wishlist)} aria-label={wishlist ? 'Remove Trail Runner 2 from wishlist' : 'Save Trail Runner 2 to wishlist'} aria-pressed={wishlist}><Heart size={22} fill={wishlist ? 'currentColor' : 'none'} /></button>
            </div>
            <div className="rating" aria-label="Rated 4.8 out of 5 from 126 reviews"><span>★★★★★</span> <a href="#reviews">4.8 (126 reviews)</a></div>
            <div className="price-row"><span className="price">$148.00</span><span className="tax-note">Price includes taxes <button aria-label="Price includes taxes"><Info size={15} /></button></span></div>
            <p className="description">A confident stride on every trail. Built with responsive cushioning, confident grip, and a breathable upper for long days outside.</p>

            <div className="option-block">
              <div className="option-heading"><span>Color</span><strong>{color.name}</strong></div>
              <div className="swatches" role="radiogroup" aria-label="Choose a color">
                {colors.map((item) => <button key={item.name} className={item.name === color.name ? 'swatch selected' : 'swatch'} onClick={() => setColor(item)} style={{ background: item.value }} role="radio" aria-checked={item.name === color.name} aria-label={item.name} />)}
              </div>
            </div>

            <div className="option-block size-block">
              <div className="option-heading"><span>Size</span><button className="guide-link" onClick={() => setGuideOpen(true)}>Size guide <span aria-hidden="true">↗</span></button></div>
              <button className={sizeOpen ? 'size-trigger open' : 'size-trigger'} onClick={() => setSizeOpen(!sizeOpen)} aria-expanded={sizeOpen} aria-controls="size-options" ref={sizeMenuRef}>{size || 'Select a size'}<ChevronDown size={18} /></button>
              {sizeOpen && <div id="size-options" className="size-options" role="listbox" aria-label="Available sizes">
                {sizes.map((item) => <button role="option" aria-selected={size === item} disabled={soldOut.includes(item)} key={item} onClick={() => { setSize(item); setSizeOpen(false); setNotice(''); }} className={size === item ? 'size-choice selected' : 'size-choice'}>{item}{soldOut.includes(item) && <span>Sold out</span>}</button>)}
              </div>}
            </div>

            <div className="purchase-row">
              <div className="quantity" aria-label="Quantity selector">
                <button aria-label="Decrease quantity" onClick={() => setQuantity(Math.max(1, quantity - 1))}><Minus size={16} /></button>
                <label htmlFor="quantity">Quantity</label><input id="quantity" type="number" min="1" max="10" value={quantity} onChange={(e) => setQuantity(Math.max(1, Math.min(10, Number(e.target.value) || 1)))} />
                <button aria-label="Increase quantity" onClick={() => setQuantity(Math.min(10, quantity + 1))}><Plus size={16} /></button>
              </div>
              <button className="add-button" onClick={addToCart}>Add to bag <ShoppingBag size={17} /></button>
            </div>
            <div className="perks"><span><Check size={16} /> Free shipping over $75</span><span><Check size={16} /> 30-day returns</span></div>
            <div className="notice" role="status" aria-live="polite">{notice}</div>
          </div>
        </section>

        <section className="details-section" aria-label="Product information">
          <div className="tabs" role="tablist" aria-label="Product information tabs">
            {['Details', 'Reviews', 'Shipping'].map((item) => <button key={item} role="tab" aria-selected={tab === item} className={tab === item ? 'tab active' : 'tab'} onClick={() => setTab(item)}>{item}{item === 'Reviews' && <span>126</span>}</button>)}
          </div>
          <div className="tab-panel" role="tabpanel">
            {tab === 'Details' && <div className="details-grid"><div><p className="eyebrow">MADE FOR THE MOVEMENT</p><h2>Light on your feet.<br />Ready for more.</h2></div><p>Trail Runner 2 brings everyday comfort to the trail. Our springy StrideFoam midsole cushions each step while the grippy rubber outsole keeps you connected to the ground. A durable ripstop upper and padded collar keep the miles feeling effortless.</p></div>}
            {tab === 'Reviews' && <div className="reviews-panel"><div><strong className="review-score">4.8</strong><span>★★★★★</span><small>Based on 126 reviews</small></div><p>“Comfortable right out of the box, with fantastic grip on wet rock. These are my new go-to trail shoes.”<br /><b>— Jamie R.</b></p></div>}
            {tab === 'Shipping' && <div className="shipping-panel"><div><h3>Free standard shipping</h3><p>Orders over $75 arrive in 3–5 business days. Express delivery is available at checkout.</p></div><div><h3>Easy returns</h3><p>Try them at home. You have 30 days to return unworn items for a full refund.</p></div></div>}
          </div>
        </section>

        <section className="faq-section" aria-labelledby="faq-title">
          <div><p className="eyebrow">NEED TO KNOW</p><h2 id="faq-title">Questions, answered.</h2></div>
          <div className="faq-list">{['Are Trail Runner 2 true to size?', 'Are these shoes waterproof?', 'How do I clean my Trail Runner 2?'].map((question, index) => <div className="faq-item" key={question}><h3><button aria-expanded={openFaq === index} aria-controls={`faq-${index}`} onClick={() => setOpenFaq(openFaq === index ? null : index)}>{question}<ChevronDown size={18} /></button></h3>{openFaq === index && <div id={`faq-${index}`} className="faq-answer">Trail Runner 2 fits true to size. If you are between sizes, we recommend choosing the larger size for a little extra room on longer adventures.</div>}</div>)}</div>
        </section>
      </main>

      <footer className="footer">
        <div className="footer-brand"><a className="logo" href="/" aria-label="Stride home"><span>STRIDE</span><small>GO FURTHER</small></a><p>Movement is for everyone.</p></div>
        <div><h2>Help</h2><a href="#contact">Contact us</a><a href="#shipping">Shipping & returns</a><a href="#faq">FAQ</a><a href="#accessibility">Accessibility</a></div>
        <div><h2>About Stride</h2><a href="#story">Our story</a><a href="#journal">Journal</a><a href="#careers">Careers</a><a href="#stores">Find a store</a></div>
        <div className="newsletter"><h2>Get 10% off your first order</h2><p>Sign up for trail notes, new drops, and inspiration.</p><form onSubmit={(e) => e.preventDefault()}><label className="sr-only" htmlFor="email">Email address</label><input id="email" type="email" placeholder="Your email address" required /><button aria-label="Subscribe to newsletter"><ArrowRight size={18} /></button></form></div>
        <div className="footer-bottom"><span>© 2025 Stride Outdoor Co.</span><span>Privacy&nbsp;&nbsp; Terms&nbsp;&nbsp; Accessibility</span><span>United States&nbsp;⌄</span></div>
      </footer>

      {guideOpen && <div className="modal-backdrop" onMouseDown={(e) => e.target === e.currentTarget && setGuideOpen(false)}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="guide-title" tabIndex="-1" ref={guideRef}><button className="modal-close" onClick={() => setGuideOpen(false)} aria-label="Close size guide"><X size={20} /></button><p className="eyebrow">FIND YOUR FIT</p><h2 id="guide-title">Size guide</h2><p className="modal-intro">Measure from your heel to your longest toe, then select your preferred sizing system.</p><div className="unit-toggle" role="radiogroup" aria-label="Size system"><button role="radio" aria-checked="true">US</button><button role="radio" aria-checked="false">EU</button></div><label htmlFor="foot-length">Foot length <span>(inches)</span></label><input id="foot-length" type="number" placeholder="e.g. 10.5" step="0.1" /><div className="guide-result"><span>Recommended size</span><strong>Enter your foot length to find your size</strong></div><button className="modal-done" onClick={() => setGuideOpen(false)}>Done</button></section></div>}
    </div>
  );
}

createRoot(document.getElementById('root')).render(<App />);

